(()=>{'use strict';
const R=window.RTS,field=document.getElementById('field'),mini=document.getElementById('minimap');
let commandArmed=false,attackMove=false;const orderButton=document.createElement('button');orderButton.id='touchOrder';orderButton.textContent='↗ Приказ';orderButton.title='Для телефона: выбери юнита, нажми «Приказ», затем коснись цели';orderButton.setAttribute('aria-pressed','false');document.querySelector('.topactions').prepend(orderButton);
function syncOrder(){R.commandMode=commandArmed;orderButton.classList.toggle('active',commandArmed);orderButton.textContent=commandArmed?'↗ Укажи цель':'↗ Приказ';orderButton.setAttribute('aria-pressed',String(commandArmed))}
function issue(p){const target=R.at(p),group=R.selected.filter(x=>x.kind==='unit'&&x.team===0);if(!group.length){R.toast('Сначала выдели своих юнитов');return}R.effect(p.x,p.y,target?.team===1?'attack':target?.kind==='resource'?'harvest':'move');group.forEach((u,i)=>{if(target?.team===1)R.order(u,target,'attack',target);else if(target?.kind==='resource'&&u.type==='worker')R.order(u,target,'harvest',target);else if(target?.kind==='building'&&target.team===0&&target.hp<target.max&&u.type==='worker')R.order(u,target,'repair',target);else {const cols=Math.max(1,Math.ceil(Math.sqrt(group.length))),row=Math.floor(i/cols),col=i%cols,spread=39;R.order(u,{x:R.clamp(p.x+(col-(cols-1)/2)*spread,24,R.world.w-24),y:R.clamp(p.y+(row-(Math.ceil(group.length/cols)-1)/2)*spread,24,R.world.h-24)},attackMove?'attackMove':'move')}});if(group.length)R.toast((attackMove?'Атака с продвижением: ':'Приказ: ')+group.length+' отряда(ов)');attackMove=false}
orderButton.onclick=()=>{if(!R.selected.some(x=>x.kind==='unit'&&x.team===0))return R.toast('Сначала выдели юнитов');commandArmed=!commandArmed;syncOrder();if(commandArmed)R.toast('Теперь коснись точки на карте')};
function targetPos(e){return R.worldPoint(e.clientX,e.clientY)}
function center(x,y){R.cam.x=R.clamp(x-innerWidth/R.zoom/2,0,Math.max(0,R.world.w-innerWidth/R.zoom));R.cam.y=R.clamp(y-innerHeight/R.zoom/2,0,Math.max(0,R.world.h-innerHeight/R.zoom))}
function selectGroup(kind){R.selected=R.units.filter(u=>u.team===0&&(kind==='worker'?u.type==='worker':u.type!=='worker'));R.hud()}
field.addEventListener('pointermove',e=>{R.mouse={x:e.clientX,y:e.clientY};if(R.drag){R.drag.ex=e.clientX;R.drag.ey=e.clientY}});
field.addEventListener('pointerdown',e=>{if(e.button===0&&!R.ended&&!R.paused){R.drag={x:e.clientX,y:e.clientY,ex:e.clientX,ey:e.clientY};field.setPointerCapture?.(e.pointerId)}});
field.addEventListener('pointerup',e=>{if(e.button!==0||R.ended||R.paused)return;const p=targetPos(e);if(R.placing){R.place(p);R.drag=null;return}if(commandArmed){issue(p);commandArmed=false;syncOrder();R.drag=null;return}if(R.drag&&Math.hypot(R.drag.ex-R.drag.x,R.drag.ey-R.drag.y)>9){const d=R.drag,l=Math.min(d.x,d.ex),r=Math.max(d.x,d.ex),t=Math.min(d.y,d.ey),b=Math.max(d.y,d.ey);R.selected=R.units.filter(u=>u.team===0).filter(u=>{const v=R.screen(u);return v.x>=l&&v.x<=r&&v.y>=t&&v.y<=b})}else{const o=R.at(p);if(e.shiftKey&&o?.team===0){if(!R.selected.includes(o))R.selected.push(o)}else R.selected=o?[o]:[]}R.drag=null;R.hud()});
field.addEventListener('contextmenu',e=>{e.preventDefault();if(R.ended||R.paused)return;if(R.placing){R.placing=null;R.toast('Строительство отменено');return}issue(targetPos(e))});
field.addEventListener('dblclick',e=>{const target=R.at(targetPos(e));if(target?.kind==='unit'&&target.team===0){R.selected=R.units.filter(x=>x.team===0&&x.type===target.type&&R.dist(x,target)<370);R.hud()}});
field.addEventListener('wheel',e=>{e.preventDefault();const p=targetPos(e);R.zoom=R.clamp(R.zoom*(e.deltaY<0?1.13:.885),.62,1.65);R.cam.x=R.clamp(p.x-e.clientX/R.zoom,0,Math.max(0,R.world.w-innerWidth/R.zoom));R.cam.y=R.clamp(p.y-e.clientY/R.zoom,0,Math.max(0,R.world.h-innerHeight/R.zoom))},{passive:false});
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;R.keys[e.key]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.repeat)return;if(e.key.toLowerCase()==='a'&&!e.ctrlKey&&!e.metaKey&&!R.paused){const selected=R.selected.filter(x=>x.kind==='unit'&&x.team===0);if(selected.length){attackMove=true;commandArmed=true;syncOrder();R.toast('Атака с продвижением: укажи точку на карте')}}if(e.key==='1')selectGroup('army');if(e.key==='2')selectGroup('worker');if(e.key.toLowerCase()==='h')center(460,930);if(e.key==='Escape'){R.placing=null;R.selected=[];commandArmed=false;attackMove=false;syncOrder();R.hud()}if(e.key===' '){R.paused=!R.paused;document.getElementById('pause').textContent=R.paused?'▶ Продолжить':'Ⅱ Пауза'}});
document.addEventListener('keyup',e=>{delete R.keys[e.key]});window.addEventListener('blur',()=>{R.keys={};R.drag=null});
mini.addEventListener('click',e=>{const rect=mini.getBoundingClientRect();center((e.clientX-rect.left)/rect.width*R.world.w,(e.clientY-rect.top)/rect.height*R.world.h)});
document.getElementById('restart').onclick=()=>{R.reset();commandArmed=false;syncOrder()};document.getElementById('playAgain').onclick=()=>{R.reset();commandArmed=false;syncOrder()};
document.getElementById('home').onclick=()=>center(460,930);document.getElementById('selectArmy').onclick=()=>selectGroup('army');document.getElementById('selectWorkers').onclick=()=>selectGroup('worker');document.getElementById('pause').onclick=()=>{R.paused=!R.paused;document.getElementById('pause').textContent=R.paused?'▶ Продолжить':'Ⅱ Пауза'};

// Edge scrolling with a mouse; touch screens keep camera motion explicit through minimap.
field.addEventListener('pointerleave',()=>{R.mouse={x:innerWidth/2,y:innerHeight/2}});
let touchStart=null;
field.addEventListener('touchstart',e=>{if(e.touches.length===2)touchStart={x:(e.touches[0].clientX+e.touches[1].clientX)/2,y:(e.touches[0].clientY+e.touches[1].clientY)/2,dist:Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY)}},{passive:true});
field.addEventListener('touchmove',e=>{if(e.touches.length!==2||!touchStart)return;e.preventDefault();const x=(e.touches[0].clientX+e.touches[1].clientX)/2,y=(e.touches[0].clientY+e.touches[1].clientY)/2,dist=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);const old=R.zoom;R.zoom=R.clamp(R.zoom*dist/touchStart.dist,.62,1.65);R.cam.x=R.clamp(R.cam.x+(touchStart.x-x)/old,0,Math.max(0,R.world.w-innerWidth/R.zoom));R.cam.y=R.clamp(R.cam.y+(touchStart.y-y)/old,0,Math.max(0,R.world.h-innerHeight/R.zoom));touchStart={x,y,dist};R.drag=null},{passive:false});
field.addEventListener('touchend',()=>{touchStart=null});
let last=0,timer=0;function frame(now){const dt=Math.min(.045,Math.max(0,(now-last)/1000||.016));last=now;R.update(dt);R.draw();timer+=dt;if(timer>.55){timer=0;R.hud()}requestAnimationFrame(frame)}
R.reset();requestAnimationFrame(frame);
})();